    nr, nc = len(rooms), len(rooms[0])

    def occupied(box):
        a, b, c, d = box
        return any(grid[r][x] not in (0, wall) for r in range(a, b) for x in range(c, d))

    def put_mirror(src, dst):
        a, b, c, d = src
        e, f, g, k = dst
        if b-a != f-e or d-c != k-g:
            return False
        for r in range(b-a):
            for x in range(d-c):
                v = grid[a+r][c+x]
                if v not in (0, wall):
                    out[e+r][k-1-x] = v
        return True

    # A 2x2 tile motif has one missing room; its counterpart is the horizontal
    # reflection of the occupied room in that same row.
    for i in range(nr - 1):
        for j in range(nc - 1):
            boxes = ((i,j),(i,j+1),(i+1,j),(i+1,j+1))
            occ = [occupied(rooms[a][b]) for a,b in boxes]
            if sum(occ) != 3:
                continue
            miss = occ.index(False)
            mi, mj = boxes[miss]
            if mj == j:
                si, sj = mi, j+1
            else:
                si, sj = mi, j
            if occupied(rooms[si][sj]):
                put_mirror(rooms[si][sj], rooms[mi][mj])
    return out
