    cs = [c for c in range(w) if all(grid[r][c] == wall for r in range(h))]
    rb, cb = [-1] + rs + [h], [-1] + cs + [w]
    rowspans = [(rb[i]+1, rb[i+1]) for i in range(len(rb)-1)]
    colspans = [(cb[j]+1, cb[j+1]) for j in range(len(cb)-1)]

    def pat(i, j):
        r0, r1 = rowspans[i]
        c0, c1 = colspans[j]
        return tuple(tuple(grid[r][c] for c in range(c0, c1)) for r in range(r0, r1))

    def occupied(p):
        return any(x not in (0, wall) for row in p for x in row)

    def mirror(p):
        return tuple(tuple(reversed(row)) for row in p)

    # Learn which neighboring room columns are mirror partners from any complete example.
    pairs = set()
    for j in range(len(colspans)-1):
        for i in range(len(rowspans)):
            a, b = pat(i, j), pat(i, j+1)
            if len(a) == len(b) and all(len(x)==len(y) for x,y in zip(a,b)) and occupied(a) and occupied(b) and mirror(a) == b:
                pairs.add((j, j+1))
                break
    for j, k in pairs:
        for i in range(len(rowspans)):
            a, b = pat(i,j), pat(i,k)
            if occupied(a) and not occupied(b):
                r0,r1=rowspans[i]; c0,c1=colspans[k]
                for rr,row in enumerate(mirror(a)):
                    for cc,x in enumerate(row):
                        if x not in (0,wall): out[r0+rr][c0+cc]=x
            elif occupied(b) and not occupied(a):
                r0,r1=rowspans[i]; c0,c1=colspans[j]
                for rr,row in enumerate(mirror(b)):
                    for cc,x in enumerate(row):
                        if x not in (0,wall): out[r0+rr][c0+cc]=x
    return out
